#!/usr/bin/env node
'use strict';

/**
 * Task-local packager that mirrors the official skill-creator packaging:
 * validates the skill folder, then zips its CONTENTS (no wrapping folder)
 * into <skill-name>.skill (a zip archive with .skill extension).
 *
 * Usage: node package_skill.cjs <skill-folder> [output-directory]
 */

const fs = require('node:fs');
const path = require('node:path');

// ---- Validation (mirrors official validate_skill.cjs) ---------------------

function collectFiles(dir, base = dir, out = []) {
  for (const name of fs.readdirSync(dir)) {
    const full = path.join(dir, name);
    if (fs.statSync(full).isDirectory()) {
      if (!['node_modules', '.git', '__pycache__'].includes(name)) {
        collectFiles(full, base, out);
      }
    } else {
      out.push(full);
    }
  }
  return out;
}

function validateSkill(skillDir) {
  if (!fs.existsSync(skillDir) || !fs.statSync(skillDir).isDirectory()) {
    throw new Error(`Path is not a directory: ${skillDir}`);
  }
  const skillMd = path.join(skillDir, 'SKILL.md');
  if (!fs.existsSync(skillMd)) throw new Error('SKILL.md not found');
  const content = fs.readFileSync(skillMd, 'utf8');
  if (!content.startsWith('---')) throw new Error('No YAML frontmatter found');
  const parts = content.split('---');
  if (parts.length < 3) throw new Error('Invalid frontmatter format');
  const fm = parts[1];
  const nameMatch = fm.match(/^name:\s*(.+)$/m);
  const descMatch = fm.match(/^description:\s*(?:'([^']*)'|"([^"]*)"|(.+))$/m);
  if (!nameMatch) throw new Error('Missing "name" in frontmatter');
  if (!descMatch) throw new Error('Description must be a single-line string');
  const name = nameMatch[1].trim();
  const description = (
    descMatch[1] !== undefined
      ? descMatch[1]
      : descMatch[2] !== undefined
        ? descMatch[2]
        : descMatch[3] || ''
  ).trim();
  if (!/^[a-z0-9-]+$/.test(name)) {
    throw new Error(`Name "${name}" should be hyphen-case`);
  }
  if (description.includes('\n')) {
    throw new Error('Description must be a single line (no newlines)');
  }
  if (description.length > 1024) {
    throw new Error('Description is too long (max 1024)');
  }
  for (const file of collectFiles(skillDir)) {
    const text = fs.readFileSync(file, 'utf8');
    if (text.includes('TODO:')) {
      throw new Error(`Unresolved TODO in ${path.relative(skillDir, file)}`);
    }
  }
  return { name };
}

// ---- Minimal ZIP writer (STORE method, UTF-8 names) ------------------------

let crcTable = null;
function crc32(buf) {
  if (!crcTable) {
    crcTable = new Int32Array(256);
    for (let n = 0; n < 256; n++) {
      let c = n;
      for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
      crcTable[n] = c;
    }
  }
  let crc = 0xffffffff;
  for (let i = 0; i < buf.length; i++) {
    crc = crcTable[(crc ^ buf[i]) & 0xff] ^ (crc >>> 8);
  }
  return (crc ^ 0xffffffff) >>> 0;
}

function dosDateTime() {
  const d = new Date();
  const year = Math.min(Math.max(d.getFullYear(), 1980), 2107);
  const time = (d.getHours() << 11) | (d.getMinutes() << 5) | (d.getSeconds() >> 1);
  const date = ((year - 1980) << 9) | ((d.getMonth() + 1) << 5) | d.getDate();
  return { time, date };
}

function buildZip(files) {
  const parts = [];
  const central = [];
  let offset = 0;
  const { time, date } = dosDateTime();
  for (const { name, data } of files) {
    const nameBuf = Buffer.from(name, 'utf8');
    const size = data.length;
    const crc = crc32(data);

    const local = Buffer.alloc(30);
    local.writeUInt32LE(0x04034b50, 0); // local file header signature
    local.writeUInt16LE(20, 4); // version needed
    local.writeUInt16LE(0x0800, 6); // flags: UTF-8 names
    local.writeUInt16LE(0, 8); // method: store
    local.writeUInt16LE(time, 10);
    local.writeUInt16LE(date, 12);
    local.writeUInt32LE(crc, 14);
    local.writeUInt32LE(size, 18);
    local.writeUInt32LE(size, 22);
    local.writeUInt16LE(nameBuf.length, 26);
    local.writeUInt16LE(0, 28); // extra length
    parts.push(local, nameBuf, data);

    const entry = Buffer.alloc(46);
    entry.writeUInt32LE(0x02014b50, 0); // central directory signature
    entry.writeUInt16LE(0x0014, 4); // version made by
    entry.writeUInt16LE(20, 6); // version needed
    entry.writeUInt16LE(0x0800, 8); // flags
    entry.writeUInt16LE(0, 10); // method: store
    entry.writeUInt16LE(time, 12);
    entry.writeUInt16LE(date, 14);
    entry.writeUInt32LE(crc, 16);
    entry.writeUInt32LE(size, 20);
    entry.writeUInt32LE(size, 24);
    entry.writeUInt16LE(nameBuf.length, 28);
    entry.writeUInt16LE(0, 30); // extra length
    entry.writeUInt16LE(0, 32); // comment length
    entry.writeUInt16LE(0, 34); // disk number start
    entry.writeUInt16LE(0, 36); // internal attributes
    entry.writeUInt32LE(0o100644 << 16, 38); // external attributes (file mode)
    entry.writeUInt32LE(offset, 42); // local header offset
    central.push(entry, nameBuf);
    offset += local.length + nameBuf.length + size;
  }

  const centralSize = central.reduce((sum, b) => sum + b.length, 0);
  const eocd = Buffer.alloc(22);
  eocd.writeUInt32LE(0x06054b50, 0); // end of central directory signature
  eocd.writeUInt16LE(0, 4);
  eocd.writeUInt16LE(0, 6);
  eocd.writeUInt16LE(files.length, 8);
  eocd.writeUInt16LE(files.length, 10);
  eocd.writeUInt32LE(centralSize, 12);
  eocd.writeUInt32LE(offset, 16);
  eocd.writeUInt16LE(0, 20); // comment length

  return Buffer.concat([...parts, ...central, eocd]);
}

function verifyZip(buffer, expectedNames) {
  if (buffer.length < 4 || buffer.readUInt32LE(0) !== 0x04034b50) {
    throw new Error('Output does not start with a ZIP local header');
  }
  const tailStart = Math.max(0, buffer.length - 65557);
  let eocdIndex = -1;
  for (let i = buffer.length - 22; i >= tailStart; i--) {
    if (buffer.readUInt32LE(i) === 0x06054b50) {
      eocdIndex = i;
      break;
    }
  }
  if (eocdIndex === -1) throw new Error('End of central directory not found');
  const count = buffer.readUInt16LE(eocdIndex + 10);
  const cdOffset = buffer.readUInt32LE(eocdIndex + 16);
  let pos = cdOffset;
  const names = [];
  for (let i = 0; i < count; i++) {
    const nameLen = buffer.readUInt16LE(pos + 28);
    names.push(buffer.toString('utf8', pos + 46, pos + 46 + nameLen));
    pos += 46 + nameLen;
  }
  const actual = [...names].sort();
  const expected = [...expectedNames].sort();
  if (actual.join('\n') !== expected.join('\n')) {
    throw new Error(`Central directory mismatch: ${actual.join(', ')}`);
  }
}

// ---- Main ------------------------------------------------------------------

function main() {
  const args = process.argv.slice(2);
  if (args.length < 1) {
    console.log('Usage: node package_skill.cjs <skill-folder> [output-directory]');
    process.exit(1);
  }
  const skillArg = args[0];
  if (skillArg.includes('..')) throw new Error('Path traversal detected');
  const skillDir = path.resolve(skillArg);
  const outputDir = path.resolve(args[1] || process.cwd());
  const skillName = path.basename(skillDir);

  try {
    console.log(`Validating skill at ${skillDir} ...`);
    const { name } = validateSkill(skillDir);
    if (name !== skillName) {
      throw new Error(`Folder name "${skillName}" does not match frontmatter name "${name}"`);
    }
    console.log('Validation passed.');

    const files = collectFiles(skillDir)
      .map((full) => ({
        name: path.relative(skillDir, full).split(path.sep).join('/'),
        data: fs.readFileSync(full),
      }))
      .sort((a, b) => (a.name < b.name ? -1 : 1));

    const archive = buildZip(files);
    verifyZip(archive, files.map((f) => f.name));

    const output = path.join(outputDir, `${skillName}.skill`);
    fs.writeFileSync(output, archive);
    const fileList = files.map((f) => `  - ${f.name} (${f.data.length} bytes)`).join('\n');
    console.log(`Success: packaged ${files.length} file(s) to ${output} (${archive.length} bytes):\n${fileList}`);
  } catch (err) {
    console.log(`Failure: ${err.message}`);
    process.exit(1);
  }
}

main();
